import type { paths } from "./schema";

// Types that tie each API address the website calls to the real API route (P3-03). The routes and their shapes come
// from the API's OpenAPI document (./schema.d.ts, generated by `pnpm api:types`).
//
// A call names its address the way the code already does, without "/api": `/tasks`, `/tasks/${id}/steps`,
// `/calendar?from=…`. The address is matched segment by segment against the routes ("{id}" matches any one segment),
// so a typo, a missing route or the wrong method is a type error, and the result has the route's response type.

export type Method = "get" | "post" | "put" | "patch" | "delete";
type Route = keyof paths;
type Op<P extends Route, M extends Method> = NonNullable<paths[P][M]>;

/** The routes that answer to a method. */
type RoutesFor<M extends Method> = { [P in Route]: [Op<P, M>] extends [never] ? never : P }[Route];

// ---------- matching an address to a route ----------
type Segments<S extends string> = S extends `${infer H}/${infer T}` ? [H, ...Segments<T>] : [S];
type WithoutQuery<U extends string> = U extends `${infer P}?${string}` ? P : U;
type SameSegments<A extends string[], B extends string[]> = A extends [infer a extends string, ...infer ar extends string[]]
  ? B extends [infer b extends string, ...infer br extends string[]]
    ? b extends `{${string}}`
      ? SameSegments<ar, br> // a path parameter: any one segment
      : a extends b
        ? SameSegments<ar, br>
        : false
    : false
  : B extends []
    ? true
    : false;

type Matching<M extends Method, U extends string> = {
  [P in RoutesFor<M>]: SameSegments<Segments<`/api${WithoutQuery<U>}`>, Segments<P & string>> extends true ? P : never;
}[RoutesFor<M>];
/** A route written exactly like the address (no "{param}" needed), like /api/emails/status. */
// (both ways: an address with a variable part, like `/emails/${id}`, must not count as exactly /emails/status)
type Exact<M extends Method, U extends string> = {
  [P in RoutesFor<M>]: P extends `/api${WithoutQuery<U>}` ? (`/api${WithoutQuery<U>}` extends P ? P : never) : never;
}[RoutesFor<M>];

/**
 * The route an address points to, for a method (never when there is none). A route written exactly like the address
 * wins over one with a parameter, as in the API's router: /emails/status is not /emails/{id}.
 */
export type RouteOf<M extends Method, U extends string> = [Exact<M, U>] extends [never] ? Matching<M, U> : Exact<M, U>;

/** An address the API has for this method; anything else is a type error (with the address in the message). */
export type ApiUrl<M extends Method, U extends string> = [RouteOf<M, U>] extends [never] ? `No ${Uppercase<M>} route for: ${U}` : U;

// ---------- what goes in and what comes back ----------
type JsonOf<T> = T extends { content: { "application/json": infer J } } ? J : never;
type Responses<P extends Route, M extends Method> = Op<P, M> extends { responses: infer R } ? R : never;

/** The successful (200) answer of the route an address points to. */
export type ResponseOf<M extends Method, U extends string> = RouteOf<M, U> extends infer P extends Route
  ? Responses<P, M> extends { 200: infer R }
    ? JsonOf<R>
    : unknown
  : never;

/** The JSON body the route accepts (undefined when it takes none). */
export type BodyOf<M extends Method, U extends string> = RouteOf<M, U> extends infer P extends Route
  ? Op<P, M> extends { requestBody?: infer B }
    ? JsonOf<NonNullable<B>> extends never
      ? undefined
      : JsonOf<NonNullable<B>>
    : undefined
  : never;

/** Whether the route needs a body (then it can't be left out). */
export type NeedsBody<M extends Method, U extends string> = RouteOf<M, U> extends infer P extends Route
  ? Op<P, M> extends { requestBody: unknown }
    ? undefined extends Op<P, M>["requestBody"]
      ? false
      : true
    : false
  : false;
